def wilson(k, n, z=1.959963984540054):
    # Wzór Wilsona zapisany niezależnie od digits.analysis.
    p = k / n
    a = p + z * z / (2 * n)
    b = z * math.sqrt(p * (1 - p) / n + z * z / (4 * n * n))
    d = 1 + z * z / n
    return (a - b) / d, (a + b) / d


